// WithoutModelHooks acknowledges that set-based writes on this query skip per-model hooks and observers; per-model writes on it are rejected.
func (q VaultQuery) WithoutModelHooks() VaultQuery { q.Query = q.Query.WithoutModelHooks(); return q }

// UpdateAll assigns the draft to every model matching this query (filters, global scopes and soft-delete visibility) in one UPDATE and returns the affected count. Managed update timestamps and field mutators apply once; per-model hooks, observers and change capture do not run.
func (q VaultQuery) UpdateAll(ctx context.Context, writer database.Transactor, draft VaultDraft) (int64, error) {
	mutation, err := draft.foundryMutation(false)
	if err != nil {
		return 0, err
	}
	return q.Query.PatchAll(ctx, writer, mutation)
}

// DeleteAll physically deletes every model matching this query in one statement and returns the affected count. Per-model hooks do not run.
func (q VaultQuery) DeleteAll(ctx context.Context, writer database.Transactor) (int64, error) {
	return q.Query.RemoveAll(ctx, writer)
}

// Increment adjusts one numeric field of every matching model by a typed delta, such as VaultFields().Field.By(1), with an optional extra draft, in one UPDATE. SQL NULL stays NULL. Per-model hooks do not run.
func (q VaultQuery) Increment(ctx context.Context, writer database.Transactor, adjustment foundryquery.Adjustment[Vault], extra ...VaultDraft) (int64, error) {
	if len(extra) > 1 {
		return 0, foundryfault.New(foundryfault.Invalid, "numeric adjustment accepts at most one extra draft")
	}
	var mutation foundryquery.Mutation[Vault]
	if len(extra) == 1 {
		var err error
		if mutation, err = extra[0].foundryMutation(false); err != nil {
			return 0, err
		}
	}
	return q.Query.AdjustAll(ctx, writer, adjustment, false, mutation)
}

// Decrement adjusts one numeric field of every matching model by a typed delta, such as VaultFields().Field.By(1), with an optional extra draft, in one UPDATE. SQL NULL stays NULL. Per-model hooks do not run.
