// Audit captures this operation's existing stored changes without getters, mutators or additional database work.
// Updates, soft deletes and restorations record assigned or changed fields plus the key; create and delete record every field.
// Standalone Compare results have no captured operation and cannot become lifecycle audit records.
func (changes VaultChanges) Audit(policy VaultAuditPolicy) (record.Model[Vault, model.ID[Vault]], error) {
	operation, present := changes.operation.Get()
	if !present {
		return record.Model[Vault, model.ID[Vault]]{}, foundryfault.New(foundryfault.Missing, "audit requires captured model changes")
	}
	item, present := changes.after.Get()
	if !present {
		item, present = changes.before.Get()
	}
	if !present {
		return record.Model[Vault, model.ID[Vault]]{}, foundryfault.New(foundryfault.Missing, "audit requires a stored model snapshot")
	}
	builder, err := record.NewBuilder(item.FoundryReference(), operation, "id", policy.ID)
	if err != nil {
		return record.Model[Vault, model.ID[Vault]]{}, err
	}
	if err = record.Capture(builder, "id", codec.ID[Vault](), changes.fields.ID, policy.ID); err != nil {
		return record.Model[Vault, model.ID[Vault]]{}, err
	}
	if err = record.Capture(builder, "token", encrypted.TextCodec(), changes.fields.Token, policy.Token); err != nil {
		return record.Model[Vault, model.ID[Vault]]{}, err
	}
	if err = record.Capture(builder, "backup", codec.Nullable(encrypted.TextCodec()), changes.fields.Backup, policy.Backup); err != nil {
		return record.Model[Vault, model.ID[Vault]]{}, err
	}
	if err = record.Capture(builder, "settings", encrypted.JSONCodec[Settings](), changes.fields.Settings, policy.Settings); err != nil {
		return record.Model[Vault, model.ID[Vault]]{}, err
	}
	if err = record.Capture(builder, "optional", codec.Nullable(encrypted.JSONCodec[Settings]()), changes.fields.Optional, policy.Optional); err != nil {
		return record.Model[Vault, model.ID[Vault]]{}, err
	}
	return builder.Build()
}

